{
  "case_id": "xsu_sg_013_specialist_declaration",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret rammer kernen (i særlige tilfælde, når art og grad ikke er tilstrækkeligt beskrevet). Det indeholder dog flere væsentlige fejl. 'Hvis dokumentationen allerede beskriver dette klart nok, peger det imod behov for speciallægeerklæring; hvis ikke, peger det for…' er forvirret og vendt forkert. 'Udbetaling Danmark kan kun kræve en speciallægeerklæring, når…for uklar' gør betingelsen udtømmende og taler om 'kræve', hvilket kilden ikke siger. Svaret nævner heller ikke de illustrative eksempler."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det andet kritiske element mangler helt: ingen af de fire eksempelgrupper nævnes (symptomintensitet/hyppighed, diskrepans mellem lægeoplysninger og ansøgers beskrivelse, tvivl om behandlingsmuligheder/prognose, tvivl om daglig funktion vs. ferieperioder). Kun det første element er dækket."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret adresserer direkte, hvornår Udbetaling Danmark kan bede om en speciallægeerklæring. Det er ufuldstændigt, men ikke irrelevant."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til en identificerbar kilde, Vejledning nr. 10157 af 5. oktober 2026 (VEJ nr 10157), via nummererede noter og kildelisten."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Den angivne vejledning findes i de frosne kilder (afsnit 5.1.3.2) og er aktuel og autoritativ for opgaven."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Kernepåstanden om 'i særlige tilfælde' og utilstrækkelig beskrivelse af art og grad understøttes af afsnit 5.1.3.2. Påstanden om, at UDK 'kun kan kræve' erklæring ved uklar dokumentation, og den vendte slutning om, at klar dokumentation 'peger imod' behovet, er ikke understøttet. Det samme gælder, at erklæringen er 'en af de former for yderligere oplysninger'. Passagen handler om speciallægeerklæring, ikke om en generel kategori af yderligere lægefaglige oplysninger. Der er heller ikke støtte for, at 'håndtering handler om, hvilken dokumentation der er nødvendig'."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en udtømmende betingelse ('kun…når dokumentationen er for uklar') og en retsvirkning om at 'kræve'. Det tilføjer også en generel regel om, at UDK kan indhente yderligere lægefaglige oplysninger, og at speciallægeerklæring er en af flere former. Ingen af delene støttes direkte af den angivne passage. Passagens 'f.eks.' viser, at eksemplerne ikke er udtømmende."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "'I særlige tilfælde' bevares. Rubrikkens krav om, at eksemplerne er illustrative og alternative, og at 'stor tvivl' bevares, er ikke opfyldt, da eksemplerne helt mangler. Svaret ender desuden med en snæver 'kun'-formulering."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret er internt modstridende. Den 'nærmere afgrænsning' siger, at klar dokumentation 'peger imod' behov, og at uklar 'peger for' anmodning. Det er i sig selv ok, men det står i spænd med den tidligere formulering om, at svaret er 'et supplerende dokumentationsskridt'. 'Kun kræve' følger ikke af de forudgående trin, som kun taler om 'kan'. Fremstillingen er også ret tåget."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Kilden bruger 'kan anmode' (i særlige tilfælde). Svaret skifter til 'kun kan kræve', hvilket gør en mulighed/et skøn til en udtømmende grænse og ændrer modaliteten fra anmode til kræve."
    }
  },
  "xhaile_coverage": {
    "A74": {
      "label": "partial",
      "reason": "Svaret dækker hovedreglen om, at UDK i særlige tilfælde kan anmode om speciallægeerklæring, når dokumentationen ikke i tilstrækkelig grad beskriver art og grad. Det udelader alle fire f.eks.-eksempler og indsnævrer reglen med 'kun'."
    }
  },
  "overall_notes": "Svaret gengiver korrekt hovedreglen, men udelader alle fire eksempelgrupper, som er et kritisk element. Det gør betingelsen udtømmende ('kun kræve'), indeholder en forvirret logik og tilføjer ustøttede udsagn. Det opfylder derfor ikke de juridiske kriterier. Kildeangivelsen er identificerbar og gyldig."
}

